98:/// POST /api/agents — start an admitted workload through the sealed door.
99:///
100:/// Three admissible forms, each exactly one identity-carried admission:
101:/// - `config.steps` → an orchestration catalog `run_workflow` operation;
102:///   structured steps are forwarded intact for sealed contract validation.
103:/// - `config.arguments` → one catalog executor operation
104:///   (`agent_<agent>_<operation>`; the sealed per-operation contract owns
105:///   the shape).
106:/// - otherwise → a declared pipeline start (`workflows.start_workflow`),
107:///   whose sealed receipt the runner consumes reactively.
108:#[allow(clippy::type_complexity)]
109:pub async fn spawn_agent_handler(
110:    headers: HeaderMap,
111:    ResponseJson(request): ResponseJson<SpawnAgentRequest>,
112:) -> Result<ResponseJson<Value>, (StatusCode, ResponseJson<Value>)> {
113:    info!(agent_type = %request.agent_type, "sealed agent workload requested");
114:    let identity = crate::handlers::identity::ghostbridge_metadata(&headers)
115:        .map_err(|refusal| (refusal_status(&refusal), refusal_body(&refusal)))?;
116:    let config = request.config.clone().unwrap_or_else(|| json!({}));
117:    let steps = config.get("steps");
118:    let operation = config
119:        .get("operation")
120:        .and_then(Value::as_str)
121:        .unwrap_or(if steps.is_some() {
122:            "run_workflow"
123:        } else {
124:            "run"
125:        });
126:
127:    let outcome = if let Some(steps) = steps {
128:        call_sealed_method(
129:            "cognitive",
130:            &agent_method_name(&request.agent_type, operation),
131:            json!({ "steps": steps, "context": config.get("context").cloned() }),
132:            &agent_capability(&request.agent_type),
133:            &identity,
134:        )
135:        .await
136:    } else if config.get("arguments").is_some() {
137:        call_sealed_method(
138:            "cognitive",
139:            &agent_method_name(&request.agent_type, operation),
140:            config
141:                .get("arguments")
142:                .cloned()
143:                .unwrap_or_else(|| json!({})),
144:            &agent_capability(&request.agent_type),
145:            &identity,
146:        )
147:        .await
148:    } else {
149:        call_sealed_method(
150:            "workflows",
151:            "start_workflow",
152:            json!({
153:                "workflow_id": request.agent_type,
154:                "params": config.get("params").cloned().unwrap_or_else(|| json!({})),
155:            }),
156:            "workflows.write",
157:            &identity,
158:        )
159:        .await
160:    };
161:
162:    match outcome {
163:        Ok(execution) => Ok(ResponseJson(json!({
164:            "accepted": true,
165:            "agent_type": request.agent_type,
166:            "execution": execution,
167:        }))),
168:        Err(error) => Err((
169:            door_error_status(&error.to_string()),
170:            json_error(&error.to_string()),
171:        )),
172:    }
173:}
