283:fn door_error_status(message: &str) -> StatusCode {
284:    let message = message.to_ascii_lowercase();
285:    // The client currently wraps both tonic statuses and numeric CallMethod
286:    // error codes as text. Prefer the explicit remote code over its message.
287:    if let Some(code) = message
288:        .split_once("remote error [")
289:        .and_then(|(_, tail)| tail.split_once(']'))
290:        .and_then(|(code, _)| code.parse::<i32>().ok())
291:    {
292:        return match op_grpc_bridge::proto::ErrorCode::try_from(code) {
293:            Ok(op_grpc_bridge::proto::ErrorCode::NotFound) => StatusCode::NOT_FOUND,
294:            Ok(op_grpc_bridge::proto::ErrorCode::PermissionDenied) => StatusCode::FORBIDDEN,
295:            Ok(op_grpc_bridge::proto::ErrorCode::ValidationFailed) => StatusCode::BAD_REQUEST,
296:            _ => StatusCode::BAD_GATEWAY,
297:        };
298:    }
299:    if message.contains("connection failed") || message.contains("parse error") {
300:        return StatusCode::BAD_GATEWAY;
301:    }
302:    if let Some(code) = message
303:        .split_once("status: ")
304:        .and_then(|(_, tail)| tail.split(',').next())
305:    {
306:        return match code.trim() {
307:            "unauthenticated" => StatusCode::UNAUTHORIZED,
308:            "permissiondenied" => StatusCode::FORBIDDEN,
309:            "notfound" => StatusCode::NOT_FOUND,
310:            "invalidargument" => StatusCode::BAD_REQUEST,
311:            _ => StatusCode::BAD_GATEWAY,
312:        };
313:    }
314:    if message.contains("access denied")
315:        || message.contains("accessdenied")
316:        || message.contains("permissiondenied")
317:        || message.contains("permission denied")
318:    {
319:        StatusCode::FORBIDDEN
320:    } else if message.contains("unauthenticated") || message.contains("credential") {
321:        StatusCode::UNAUTHORIZED
322:    } else if message.contains("notfound") || message.contains("not found") {
323:        StatusCode::NOT_FOUND
324:    } else if message.contains("invalidargument") {
325:        StatusCode::BAD_REQUEST
326:    } else {
327:        StatusCode::BAD_GATEWAY
328:    }
329:}
