1075:async fn provision_verified_user(
1076:    state: &Arc<AppState>,
1077:    user: PrivacyUser,
1078:) -> anyhow::Result<PrivacyUser> {
1079:    crate::privacy_network::ensure_host_privacy_network().await?;
1080:    let container_name = crate::privacy_container::ensure_user_container(&user).await?;
1081:    let route_id =
1082:        crate::privacy_routes::publish_user_privacy_route(&user, Some(container_name.as_str()))
1083:            .await?;
1084:    crate::privacy_openflow::publish_openflow_for_privacy_routes().await?;
1085:
1086:    let already_connected = user.privacy_network_connected
1087:        && user.privacy_container_name.as_deref() == Some(container_name.as_str())
1088:        && user.privacy_route_id.as_deref() == Some(route_id.as_str());
1089:    if already_connected {
1090:        return Ok(user);
1091:    }
1092:
1093:    state
1094:        .user_store
1095:        .mark_privacy_network_connected(&user.id, container_name, route_id)
1096:        .await
