1:use super::UnifiedOrchestrator;
2:use regex::Regex;
3:use simd_json::prelude::*;
4:use simd_json::{OwnedValue as Value, json};
5:use tracing::info;
6:
7:impl UnifiedOrchestrator {
8:    /// Extract tool calls from text (for models without native tool calling)
9:    ///
10:    /// Supports:
11:    /// - XML tags: `<tool_call>name({args})</tool_call>`
12:    /// - Code blocks: ` ```tool ... ``` `
13:    /// - Direct calls: `tool_name({args})`
14:    #[allow(dead_code)]
15:    pub(crate) fn extract_tool_calls_from_text(
16:        &self,
17:        text: &str,
18:        available: &[String],
19:    ) -> Vec<(String, Value)> {
20:        let mut calls = Vec::new();
21:
22:        // Pattern 1: <tool_call>name({"arg": "val"})</tool_call> (with multiline support)
23:        if let Ok(re) =
24:            Regex::new(r"(?s)<tool_call>\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\((.*?)\)\s*</tool_call>")
25:        {
26:            for cap in re.captures_iter(text) {
27:                if let (Some(name), Some(args)) = (cap.get(1), cap.get(2)) {
28:                    let tool_name = name.as_str().to_string();
29:                    if available.contains(&tool_name) {
30:                        let raw = args.as_str().trim().to_string();
31:                        if let Ok(parsed) = serde_json::from_str(&raw) {
32:                            info!("Extracted tool call from XML tags: {}", tool_name);
33:                            calls.push((tool_name, parsed));
34:                        }
35:                    }
36:                }
37:            }
38:        }
39:
40:        // If we found XML tag calls, use those (preferred format)
41:        if !calls.is_empty() {
42:            return calls;
43:        }
44:
45:        // Pattern 2: ```tool or ```tool_code blocks
46:        if let Ok(re) = Regex::new(r"(?s)```(?:tool|tool_code)\s*\n(.+?)\n```") {
47:            for cap in re.captures_iter(text) {
48:                if let Some(block) = cap.get(1) {
49:                    // Parse tool calls from inside the block
