114:/// (newlines, tabs, NULs). Used only for diagnostic warnings about malformed
115:/// proxy headers; never for security decisions.
116:fn sanitize_header_for_log(raw: &str) -> String {
117:    const MAX: usize = 64;
118:    let mut out = String::with_capacity(raw.len().min(MAX) + 8);
119:    for (i, b) in raw.bytes().enumerate() {
120:        if i >= MAX {
121:            out.push('\u{2026}'); // ellipsis
122:            break;
123:        }
124:        if (0x20..0x7f).contains(&b) && b != b'\\' {
125:            out.push(b as char);
126:        } else {
127:            out.push_str(&format!("\\x{:02x}", b));
128:        }
129:    }
130:    out
131:}
132:
133:/// Parse a single XFF / X-Real-IP segment, rejecting anything that cannot be
134:/// a clean IP address. Returns `None` on malformed input.
135:///
136:/// Accepted forms:
137:///   * Plain IPv4 (`1.2.3.4`) or IPv6 (`::1`)
138:///   * IPv4 with port (`1.2.3.4:8080`) \u2014 port stripped, address parsed
139:///   * Bracketed IPv6 with port (`[::1]:1234`) \u2014 brackets+port stripped
140:///
141:/// Rejected: anything containing whitespace, commas, semicolons, NULs, or
142:/// other control characters, and anything that is not ultimately a valid
143:/// `IpAddr` after the port-strip.
144:fn parse_forwarded_segment(segment: &str) -> Option<IpAddr> {
145:    let trimmed = segment.trim();
146:    if trimmed.is_empty() {
147:        return None;
148:    }
149:    // Reject anything that smuggles a second value or control chars into
150:    // the first segment (e.g. `1.2.3.4, evil`, `1.2.3.4;drop`, NULs, etc.).
151:    if trimmed
152:        .bytes()
153:        .any(|b| matches!(b, b',' | b';' | b'\n' | b'\r' | b'\0' | b' ' | b'\t'))
154:    {
155:        return None;
156:    }
157:
158:    // Strip the optional `[ipv6]:port` brackets and `:port` suffix tolerated
159:    // by some proxies. We only need the address.
160:    let candidate: &str = if let Some(stripped) = trimmed.strip_prefix('[') {
161:        // [::1]:1234 form \u2014 take everything up to (but not including) the
162:        // first `]`. The trailing `:port` (if any) is discarded.
163:        stripped.split(']').next().unwrap_or(stripped)
164:    } else if let Some((host, _port)) = trimmed.rsplit_once(':') {
165:        // Possibly IPv4-with-port. An unbracketed IPv6 also matches this
166:        // pattern (it contains colons), so we have to be careful.
167:        // Treat as `host:port` only if `host` looks like exactly 4 dotted
168:        // numeric octets (i.e. a candidate IPv4). Otherwise leave the full
169:        // string and let `IpAddr::from_str` decide (which will correctly
170:        // accept unbracketed IPv6 like `::1`).
171:        if looks_like_ipv4_octets(host) {
172:            host
173:        } else {
174:            trimmed
175:        }
176:    } else {
177:        trimmed
178:    };
179:
180:    IpAddr::from_str(candidate).ok()
181:}
182:
183:/// Returns true iff `s` is exactly 4 dot-separated numeric octets, each
184:/// 1\u20133 ASCII digits. Does NOT validate the 0\u2013255 range \u2014 that is left to
185:/// `IpAddr::from_str` which will reject e.g. `999.0.0.1`.
186:fn looks_like_ipv4_octets(s: &str) -> bool {
187:    let mut count = 0usize;
188:    for part in s.split('.') {
189:        count += 1;
190:        if count > 4 {
191:            return false;
192:        }
193:        if part.is_empty() || part.len() > 3 || !part.bytes().all(|b| b.is_ascii_digit()) {
194:            return false;
195:        }
196:    }
197:    count == 4
198:}
199:
200:/// Extract the client IP. Proxy headers (`X-Forwarded-For`, `X-Real-IP`) are
201:/// only honoured when the TCP peer is a known trusted proxy. Malformed header
202:/// values fall back to the real socket peer rather than a placeholder.
203:pub fn extract_ip(headers: &HeaderMap, addr: Option<&SocketAddr>) -> String {
204:    if addr.map(is_trusted_proxy).unwrap_or(false) {
205:        // X-Forwarded-For \u2014 take leftmost (original client).
206:        if let Some(forwarded) = headers.get("x-forwarded-for")
207:            && let Ok(s) = forwarded.to_str()
208:            && let Some(first) = s.split(',').next()
209:        {
210:            if let Some(ip) = parse_forwarded_segment(first) {
211:                return ip.to_string();
212:            }
213:            warn!(
214:                raw = %sanitize_header_for_log(first),
215:                "Rejected malformed X-Forwarded-For first segment"
216:            );
217:        }
218:
219:        // X-Real-IP fallback.
220:        if let Some(real_ip) = headers.get("x-real-ip")
221:            && let Ok(s) = real_ip.to_str()
222:        {
223:            if let Some(ip) = parse_forwarded_segment(s) {
224:                return ip.to_string();
225:            }
226:            warn!(
227:                raw = %sanitize_header_for_log(s),
228:                "Rejected malformed X-Real-IP"
229:            );
230:        }
231:    }
232:
233:    // Real socket peer \u2014 not spoofable.
234:    if let Some(addr) = addr {
235:        return addr.ip().to_string();
236:    }
237:
238:    // No socket info at all: fall back to the unspecified address. This
239:    // classifies as a public-zone caller in `AccessZone::from_ip`, which is
240:    // the safe default.
241:    "0.0.0.0".to_string()
242:}
243:
244:/// Middleware that attaches an `AccessZone` to the request based on the
245:/// client IP. There is no header-based zone override; all elevation must go
246:/// through the gateway's WireGuard-authenticated session ledger.
247:///
248:/// TODO(audit #4 follow-up): if a header-based override is ever reintroduced,
249:/// it MUST (a) be opt-in via env var, (b) be accepted only from
250:/// `is_trusted_proxy()` peers, and (c) carry a short-lived HMAC-signed token
251:/// rather than a static secret.
252:pub async fn ip_security_middleware(mut request: Request, next: Next) -> Response {
253:    let connect_info = request
254:        .extensions()
255:        .get::<ConnectInfo<SocketAddr>>()
256:        .copied();
257:    let headers = request.headers();
258:    let addr = connect_info.map(|ci| ci.0);
259:    // `client_ip` is informational only; we feed the same value into
260:    // `AccessZone::from_ip` below, so logging it is never security-relevant.
261:    let client_ip = extract_ip(headers, addr.as_ref());
262:
263:    let zone = AccessZone::from_ip(&client_ip);
264:    debug!(
265:        ip = %client_ip,
266:        zone = ?zone,
267:        "Resolved request access zone"
268:    );
269:
270:    request.extensions_mut().insert(zone);
271:    next.run(request).await
272:}
