206:            Ok("1") | Ok("true") | Ok("TRUE") | Ok("yes") | Ok("YES")
207:        );
208:    let mut frames = vec![event(
209:        "state_reset",
210:        json!({
211:            "scope": "public_projection", "catalog_hash": &cursor.catalog_hash,
212:            "state_generation": cursor.generation.to_string(),
213:            "frame_kind": StateFrameKind::InitialState as i32,
214:        }),
215:    )?];
216:    if hydrate {
217:        let allow = sse_plugin_allowlist();
218:        let mut states = Vec::new();
