225:            // Serialize the original sealed JSON, never a typed schema with new
226:            // serde defaults inserted by the currently compiled consumer.
227:            let schema: Value = serde_json::from_str(&plugin.schema_json)?;
228:            frames.push(event(
229:                "schema_update",
230:                json!({
231:                    "plugin_id": &plugin_id, "object_path": &path,
232:                    "property_name": &plugin.schema_hash, "new_value": schema,
233:                    "event_id": "0", "tags": [], "change_type": ChangeType::SchemaMigration as i32,
234:                    "frame_kind": StateFrameKind::InitialState as i32,
235:                    "schema_hash": &plugin.schema_hash, "catalog_hash": &cursor.catalog_hash,
236:                    "state_generation": cursor.generation.to_string(), "removed": false,
237:                }),
238:            )?);
239:            let absent = plugin.state.is_none();
240:            states.push(event("state_update", json!({
241:                "plugin_id": plugin_id, "object_path": path, "property_name": null,
242:                "new_value": plugin.state, "event_id": "0", "tags": [],
243:                "change_type": if absent { ChangeType::ObjectRemoved as i32 } else { ChangeType::PropertySet as i32 },
244:                "frame_kind": StateFrameKind::InitialState as i32,
245:                "schema_hash": plugin.schema_hash, "catalog_hash": &cursor.catalog_hash,
246:                "state_generation": cursor.generation.to_string(), "removed": absent, "replace": true,
247:            }))?);
248:            selected_bytes = selected_bytes
249:                .checked_add(frames.last().context("schema frame missing")?.data.len())
250:                .and_then(|bytes| {
251:                    bytes.checked_add(states.last().map_or(0, |frame| frame.data.len()))
252:                })
253:                .context("state hydration size overflow")?;
254:            ensure!(
255:                selected_bytes <= MAX_HYDRATION_BYTES,
256:                "state hydration exceeds 16 MiB"
257:            );
258:            ensure!(
259:                frames.len() + states.len() < MAX_HYDRATION_FRAMES,
260:                "state hydration exceeds 4096 frames"
261:            );
