328:fn state_event_stream(
329:    mut rx: broadcast::Receiver<SseEvent>,
330:    mut refresh: impl FnMut() -> Refresh + Send + 'static,
331:) -> impl Stream<Item = std::result::Result<Event, Infallible>> + Send {
332:    async_stream::stream! {
333:        let initial = match refresh().await {
334:            Ok(hydration) => hydration,
335:            Err(error) => { tracing::warn!(%error, "Cannot hydrate SSE from committed SHM"); yield Ok(unavailable()); return; }
336:        };
337:        let mut baseline = initial.cursor;
338:        let mut last_forwarded = baseline.generation;
339:        for frame in initial.frames { yield Ok(wire(frame)); }
340:        loop {
341:            let received = rx.recv().await;
342:            let (pending, resync) = match received {
343:                Ok(frame) if frame.event_type == "state_resync" => (None, true),
344:                Ok(frame) if matches!(frame.event_type.as_str(), "state_update" | "schema_update" | "state_heartbeat") => {
345:                    let cursor = match state_cursor(&frame) {
346:                        Ok(cursor) => cursor,
347:                        Err(error) => { tracing::warn!(%error, "Invalid SSE state framing"); yield Ok(unavailable()); return; }
348:                    };
349:                    if cursor.catalog_hash == baseline.catalog_hash && cursor.generation <= baseline.generation {
350:                        // This frame was queued before fresh hydration. Every
351:                        // selected public root is already represented above.
352:                        continue;
353:                    }
354:                    let resync = cursor.catalog_hash != baseline.catalog_hash || cursor.generation < last_forwarded;
355:                    (Some((frame, cursor)), resync)
356:                }
357:                Ok(frame) if frame.event_type == "audit_event" => continue,
358:                Ok(frame) => { yield Ok(wire(frame)); continue; }
359:                Err(broadcast::error::RecvError::Lagged(_)) => {
360:                    yield Ok(Event::default().event("stream_gap").data("{\"state\":\"rehydrating\"}"));
361:                    (None, true)
362:                }
363:                Err(broadcast::error::RecvError::Closed) => return,
364:            };
365:            if resync {
366:                let fresh = match refresh().await {
367:                    Ok(hydration) => hydration,
368:                    Err(error) => { tracing::warn!(%error, "Cannot rehydrate SSE from committed SHM"); yield Ok(unavailable()); return; }
369:                };
370:                baseline = fresh.cursor;
371:                last_forwarded = baseline.generation;
372:                for frame in fresh.frames { yield Ok(wire(frame)); }
373:            }
374:            if let Some((frame, cursor)) = pending
375:                && cursor.catalog_hash == baseline.catalog_hash && cursor.generation > baseline.generation && cursor.generation >= last_forwarded {
376:                    last_forwarded = cursor.generation;
377:                    yield Ok(wire(frame));
378:                }
379:        }
380:    }
381:}
