125:fn read_committed_tree_in(state_dir: &str, catalog_dir: &Path) -> Result<CommittedStateTree> {
126:    let sealed = sealed_catalog(catalog_dir)?;
127:    let mut schemas = BTreeMap::new();
128:    for (plugin, schema_hash) in &sealed.plugins {
129:        schemas.insert(
130:            plugin.clone(),
131:            (
132:                validate_sealed_plugin(catalog_dir, plugin)?,
133:                original_schema_json(catalog_dir, plugin, schema_hash)?,
134:            ),
135:        );
136:    }
137:    ensure_manifest_unchanged(catalog_dir, &sealed.manifest)?;
138:    let ids: Vec<String> = sealed.plugins.keys().cloned().collect();
139:    let snapshot = op_core::projection_shm::read_projection_snapshot_in(state_dir, &ids)?;
140:    ensure_manifest_unchanged(catalog_dir, &sealed.manifest)?;
141:
142:    let mut plugins = BTreeMap::new();
143:    for (plugin, schema_hash) in sealed.plugins {
144:        let (schema, schema_json) = schemas
145:            .remove(&plugin)
146:            .context("validated schema disappeared")?;
147:        let state = snapshot
148:            .states
149:            .get(&plugin)
150:            .map(|bytes| decode_public_state(&plugin, &schema, bytes))
151:            .transpose()?
152:            .flatten();
153:        plugins.insert(
154:            plugin.clone(),
155:            CommittedPluginState {
156:                schema_json,
157:                schema_hash,
158:                schema,
159:                state,
160:            },
161:        );
162:    }
163:    Ok(CommittedStateTree {
164:        catalog_hash: sealed.catalog_hash,
165:        projection_generation: snapshot.generation,
166:        plugins,
167:    })
168:}
