172:    let bytes = std::fs::read(&path)
173:        .with_context(|| format!("read sealed plugin blob {}", path.display()))?;
174:    let blob = op_blob::BlobRef::from_manifest_pinned(&bytes, schema_hash)
175:        .map_err(|error| anyhow::anyhow!("invalid sealed plugin blob: {error}"))?;
176:    let manifest = blob
177:        .manifest()
178:        .map_err(|error| anyhow::anyhow!("invalid sealed plugin manifest: {error}"))?;
179:    ensure!(
180:        manifest.plugin_id == plugin
181:            && manifest.schema_hash == schema_hash
182:            && manifest.blob_type == "active_reflection",
183:        "sealed plugin blob identity does not match catalog"
184:    );
185:    Ok(blob.schema_json().to_string())
