194:    let catalog_hash = manifest
195:        .get("catalog_hash")
196:        .and_then(serde_json::Value::as_str)
197:        .filter(|hash| hash.len() == 64 && hash.bytes().all(|byte| byte.is_ascii_hexdigit()))
198:        .context("sealed catalog manifest has no valid catalog hash")?
199:        .to_string();
