314:    /// Start the event bridge from gRPC to SSE
315:    pub fn start_event_bridge(self: Arc<Self>) {
316:        let state = self.clone();
317:
318:        // Lungs owns live subscribe. Keep this bridge off unless an operator
319:        // explicitly re-enables the legacy HTTP SSE fan-out.
320:        let bridge_enabled = matches!(
321:            std::env::var("OP_WEB_SSE_BRIDGE").as_deref(),
322:            Ok("1") | Ok("true") | Ok("TRUE") | Ok("yes") | Ok("YES")
323:        );
324:        if !bridge_enabled {
325:            info!(
326:                "gRPC -> SSE bridge disabled (lungs owns live state; set OP_WEB_SSE_BRIDGE=1 to re-enable)"
327:            );
328:            return;
329:        }
330:
331:        // 1. State updates bridge
332:        let state_clone = state.clone();
333:        tokio::spawn(async move {
334:            info!("Starting gRPC -> SSE state updates bridge...");
335:            loop {
336:                let plugins = crate::sse::sse_plugin_allowlist();
337:                match state_clone
338:                    .grpc_client
339:                    .subscribe(plugins, vec![], vec![])
340:                    .await
341:                {
342:                    Ok(mut stream) => {
343:                        info!("Subscribed to gRPC state updates");
344:                        state_clone
345:                            .sse_broadcaster
346:                            .broadcast("state_resync", "{\"reason\":\"upstream_connected\"}");
347:                        while let Some(msg_result) = stream.next().await {
348:                            match msg_result {
349:                                Ok(msg) => match crate::sse::state_message_event(&msg) {
350:                                    Ok(event) => state_clone
351:                                        .sse_broadcaster
352:                                        .broadcast(&event.event_type, &event.data),
353:                                    Err(error) => {
354:                                        warn!(%error, "Invalid committed state frame; reconnecting");
355:                                        break;
356:                                    }
357:                                },
358:                                Err(e) => {
359:                                    warn!("gRPC subscription stream error: {}", e);
360:                                    break;
361:                                }
362:                            }
363:                        }
364:                        state_clone.sse_broadcaster.broadcast(
365:                            "state_unavailable",
366:                            "{\"reason\":\"upstream_disconnected\"}",
367:                        );
368:                        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
369:                    }
370:                    Err(e) => {
371:                        warn!("Failed to subscribe to gRPC updates: {}. Retrying...", e);
372:                        state_clone.sse_broadcaster.broadcast(
373:                            "state_unavailable",
374:                            "{\"reason\":\"upstream_unavailable\"}",
375:                        );
376:                        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
377:                    }
378:                }
379:            }
380:        });
381:
382:        // Audit history is privileged and is never subscribed with the web
383:        // service identity for this shared, unauthenticated SSE endpoint.
384:    }
