41:impl DoorProxy {
42:    /// Build from the settings op-web's own door client uses:
43:    /// `OP_DBUS_GRPC_ADDR`, `OP_DBUS_GRPC_CA_FILE` and `OP_DBUS_GRPC_TLS_DOMAIN`.
44:    pub fn from_env() -> anyhow::Result<Self> {
45:        let address = crate::state::door_grpc_addr();
46:        let ca_pem = match std::env::var("OP_DBUS_GRPC_CA_FILE") {
47:            Ok(path) if !path.trim().is_empty() => Some(
48:                std::fs::read(path.trim())
49:                    .with_context(|| format!("reading OP_DBUS_GRPC_CA_FILE={path}"))?,
50:            ),
51:            _ => None,
52:        };
53:        let domain = std::env::var("OP_DBUS_GRPC_TLS_DOMAIN")
54:            .ok()
55:            .map(|domain| domain.trim().to_string())
56:            .filter(|domain| !domain.is_empty());
57:        Self::new(&address, ca_pem, domain)
58:    }
