60:    pub fn new(
61:        address: &str,
62:        ca_pem: Option<Vec<u8>>,
63:        domain: Option<String>,
64:    ) -> anyhow::Result<Self> {
65:        let mut endpoint = Endpoint::from_shared(address.to_string())
66:            .with_context(|| format!("invalid door address {address}"))?
67:            .connect_timeout(Duration::from_secs(5));
68:        if address.starts_with("https://") {
69:            let mut tls = ClientTlsConfig::new().with_native_roots();
70:            if let Some(pem) = ca_pem {
71:                tls = tls.ca_certificate(Certificate::from_pem(pem));
72:            }
73:            if let Some(domain) = domain {
74:                tls = tls.domain_name(domain);
75:            }
76:            endpoint = endpoint
77:                .tls_config(tls)
78:                .with_context(|| format!("TLS config for {address}"))?;
79:        }
80:        Ok(Self {
81:            channel: endpoint.connect_lazy(),
82:        })
83:    }
