85:    /// Forward one gRPC-Web call and return the door's response as it came.
86:    pub async fn forward(&self, request: Request) -> Response {
87:        let (mut parts, body) = request.into_parts();
88:        let client_version = parts.version;
89:        strip_hop_by_hop(&mut parts.headers);
