275:    if name.is_empty()
276:        || name.len() > 64
277:        || !name
278:            .bytes()
279:            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
280:        || request
281:            .groups
282:            .iter()
283:            .any(|group| !known_groups.contains(group))
284:        || request
285:            .preset
286:            .as_ref()
