654:<body>
655:    <div class="container">
656:        <header>
657:            <h1>🔧 Tool Groups Admin</h1>
658:            <p class="subtitle">Manage tool groups by domain (~5 tools each) • Stay under Cursor's 40-tool limit</p>
659:            
660:            <div class="stats-row">
661:                <div class="stat">
662:                    <div class="stat-value" id="enabled-count">0</div>
663:                    <div class="stat-label">Groups Enabled</div>
664:                </div>
665:                <div class="stat">
666:                    <div class="stat-value" id="tool-count">0</div>
667:                    <div class="stat-label">Total Tools</div>
668:                </div>
669:                <div class="stat">
670:                    <div class="stat-value success" id="remaining">40</div>
671:                    <div class="stat-label">Remaining</div>
672:                </div>
673:                <div style="flex: 1;"></div>
674:                <div class="stat">
675:                    <div class="access-badge" id="access-zone">
676:                        <span>🔒</span>
677:                        <span>Detecting...</span>
678:                    </div>
679:                    <div class="stat-label">Your Access Level</div>
680:                </div>
681:            </div>
682:        </header>
683:        
684:        <div class="main-layout">
685:            <div class="groups-column">
686:                <div id="domains-container">
687:                    <!-- Domains populated by JS -->
688:                </div>
689:            </div>
690:            
691:            <div class="sidebar">
692:                <div class="sidebar-header">
693:                    <strong>Configuration</strong>
694:                </div>
695:                <div class="sidebar-content">
696:                    <div class="presets-section">
697:                        <h4 style="margin-bottom: 0.5rem; font-size: 0.85rem; color: var(--text-secondary);">Quick Presets</h4>
698:                        <div id="presets-container">
699:                            <!-- Presets populated by JS -->
700:                        </div>
701:                    </div>
702:                    
703:                    <h4 style="margin-bottom: 0.5rem; font-size: 0.85rem; color: var(--text-secondary);">
704:                        Enabled Groups (<span id="sidebar-count">0</span>)
705:                    </h4>
706:                    <ul class="selected-list" id="selected-list">
707:                        <!-- Populated by JS -->
708:                    </ul>
709:                </div>
710:                <div class="sidebar-actions">
711:                    <div style="display: flex; gap: 0.5rem;">
712:                        <select id="saved-profiles" style="flex: 1;">
713:                            <option value="">Load profile...</option>
714:                        </select>
715:                        <button class="btn-secondary" onclick="loadProfile()">Load</button>
716:                    </div>
717:                    <div style="display: flex; gap: 0.5rem;">
718:                        <input type="text" id="profile-name" placeholder="Profile name" value="default" style="flex: 1;">
719:                        <button class="btn-primary" onclick="saveProfile()">💾 Save</button>
720:                    </div>
721:                    
722:                    <div class="config-output" id="config-output">
723:                        <strong>MCP Endpoint:</strong>
724:                        <pre id="endpoint-display"></pre>
725:                        <button class="btn-secondary" style="width: 100%; margin-top: 0.5rem;" onclick="copyConfig()">📋 Copy Config</button>
726:                    </div>
727:                </div>
728:            </div>
729:        </div>
730:    </div>
731:    
732:    <script>
733:        const MAX_TOOLS = 40;
734:        let allGroups = {};
735:        let enabledGroups = new Set();
736:        let groupCounts = {};
737:        let accessZone = 'public';
738:        let currentPreset = null;
739:        
740:        const domainIcons = {
741:            'core': '💎', 'files': '📁', 'shell': '💻', 'systemd': '⚙️',
742:            'network': '🌐', 'dbus': '🔌', 'monitoring': '📊', 'git': '📦',
743:            'devops': '🚀', 'security': '🔒', 'business': '💼', 'architect': '🏗️',
744:            'database': '🗄️', 'ovs': '🔀', 'agents': '🤖', 'system': '⚠️'
745:        };
746:        
747:        async function init() {
748:            await Promise.all([
749:                loadGroups(),
750:                loadPresets(),
751:                loadAccessZone(),
752:                loadSavedProfiles()
753:            ]);
754:        }
755:        
756:        async function loadGroups() {
757:            const res = await fetch('/groups-admin/api/groups');
758:            const data = await res.json();
759:            
760:            const container = document.getElementById('domains-container');
761:            container.innerHTML = '';
762:            
763:            data.domains.forEach(domain => {
764:                const icon = domainIcons[domain.domain] || '📦';
765:                const isSystem = domain.domain === 'system';
766:                
767:                const section = document.createElement('div');
768:                section.className = 'domain-section';
769:                section.innerHTML = `
770:                    <div class="domain-header" onclick="toggleDomain('${domain.domain}')">
771:                        <span class="domain-name">
772:                            <span class="domain-icon">${icon}</span>
773:                            ${domain.domain.charAt(0).toUpperCase() + domain.domain.slice(1)}
774:                        </span>
775:                        <span class="domain-meta">${domain.groups.length} groups • ~${domain.total_tools} tools</span>
776:                    </div>
777:                    <div class="domain-groups" id="domain-${domain.domain}">
778:                        ${domain.groups.map(g => {
779:                            allGroups[g.id] = g;
780:                            groupCounts[g.id] = g.count;
781:                            const locked = !canAccessSecurity(g.security);
782:                            return `
783:                                <div class="group-card ${locked ? 'locked' : ''}" 
784:                                     data-id="${g.id}" 
785:                                     onclick="${locked ? '' : `toggleGroup('${g.id}')`}">
786:                                    <input type="checkbox" class="group-checkbox" 
787:                                           id="cb-${g.id}" 
788:                                           ${locked ? 'disabled' : ''}
789:                                           onchange="toggleGroup('${g.id}')">
790:                                    <div class="group-info">
791:                                        <div class="group-name">${g.name}</div>
792:                                        <div class="group-desc">${g.description}</div>
793:                                    </div>
794:                                    <div class="group-badges">
795:                                        <span class="badge badge-count">~${g.count}</span>
796:                                        <span class="badge badge-${g.security}">${g.security}</span>
797:                                    </div>
798:                                </div>
799:                            `;
800:                        }).join('')}
801:                    </div>
802:                `;
803:                container.appendChild(section);
804:            });
805:            
806:            // Expand core by default
807:            document.getElementById('domain-core')?.classList.add('expanded');
808:        }
809:        
810:        async function loadPresets() {
811:            const res = await fetch('/groups-admin/api/presets');
812:            const data = await res.json();
813:            
814:            const container = document.getElementById('presets-container');
815:            container.innerHTML = data.presets.map(p => {
816:                const locked = p.requires_localhost && accessZone !== 'localhost' && accessZone !== 'trustedmesh';
817:                return `
818:                    <button class="preset-btn ${locked ? 'locked' : ''}" 
819:                            data-preset="${p.id}"
820:                            onclick="${locked ? '' : `applyPreset('${p.id}', ${JSON.stringify(p.groups)})`}"
821:                            ${locked ? 'disabled' : ''}>
822:                        <div class="preset-name">${p.name}</div>
823:                        <div class="preset-desc">${p.description}</div>
824:                        <div class="preset-count">${p.groups.length} groups • ~${p.estimated_total} tools${locked ? ' • 🔒 localhost only' : ''}</div>
825:                    </button>
826:                `;
827:            }).join('');
828:        }
829:        
830:        async function loadAccessZone() {
831:            const res = await fetch('/groups-admin/api/access-zone');
832:            const data = await res.json();
833:            accessZone = data.zone;
834:            
835:            const badge = document.getElementById('access-zone');
836:            const icons = { localhost: '🏠', trustedmesh: '🔗', privatenetwork: '🏢', public: '🌍' };
837:            badge.className = `access-badge ${data.zone}`;
838:            badge.innerHTML = `<span>${icons[data.zone] || '🔒'}</span><span>${data.description}</span>`;
839:        }
840:        
841:        async function loadSavedProfiles() {
842:            const res = await fetch('/groups-admin/api/profiles');
843:            const data = await res.json();
844:            
845:            const select = document.getElementById('saved-profiles');
846:            select.innerHTML = '<option value="">Load profile...</option>';
847:            data.profiles.forEach(name => {
848:                select.innerHTML += `<option value="${name}">${name}</option>`;
849:            });
850:        }
851:        
852:        function canAccessSecurity(level) {
853:            if (accessZone === 'localhost' || accessZone === 'trustedmesh') return true;
854:            if (accessZone === 'privatenetwork') return level !== 'restricted';
855:            return level === 'public' || level === 'standard';
856:        }
857:        
858:        function toggleDomain(domain) {
859:            document.getElementById(`domain-${domain}`).classList.toggle('expanded');
860:        }
861:        
862:        function toggleGroup(id, forceState) {
863:            const group = allGroups[id];
864:            if (!group || !canAccessSecurity(group.security)) return;
865:            
866:            const isEnabled = forceState !== undefined ? forceState : !enabledGroups.has(id);
867:            const count = groupCounts[id] || 0;
868:            
869:            if (isEnabled) {
870:                if (getTotalTools() + count > MAX_TOOLS) {
871:                    alert(`Cannot enable "${group.name}" - would exceed ${MAX_TOOLS} tool limit`);
872:                    return;
873:                }
874:                enabledGroups.add(id);
875:                // Enable dependencies
876:                (group.dependencies || []).forEach(dep => {
877:                    if (!enabledGroups.has(dep)) toggleGroup(dep, true);
878:                });
879:            } else {
880:                enabledGroups.delete(id);
881:            }
882:            
883:            currentPreset = null;
884:            updateUI();
885:        }
886:        
887:        function applyPreset(presetId, groups) {
888:            enabledGroups.clear();
889:            groups.forEach(g => {
890:                if (allGroups[g] && canAccessSecurity(allGroups[g].security)) {
891:                    enabledGroups.add(g);
892:                }
893:            });
894:            currentPreset = presetId;
895:            updateUI();
896:            
897:            document.querySelectorAll('.preset-btn').forEach(btn => {
898:                btn.classList.toggle('active', btn.dataset.preset === presetId);
899:            });
900:        }
901:        
902:        function getTotalTools() {
903:            return Array.from(enabledGroups).reduce((sum, id) => sum + (groupCounts[id] || 0), 0);
904:        }
905:        
906:        function updateUI() {
907:            // Update checkboxes
908:            document.querySelectorAll('.group-card').forEach(card => {
909:                const id = card.dataset.id;
910:                const enabled = enabledGroups.has(id);
911:                card.classList.toggle('selected', enabled);
912:                const cb = card.querySelector('.group-checkbox');
913:                if (cb) cb.checked = enabled;
914:            });
915:            
916:            // Update stats
917:            const total = getTotalTools();
918:            const remaining = MAX_TOOLS - total;
919:            
920:            document.getElementById('enabled-count').textContent = enabledGroups.size;
921:            document.getElementById('tool-count').textContent = total;
922:            document.getElementById('remaining').textContent = remaining;
923:            document.getElementById('sidebar-count').textContent = enabledGroups.size;
924:            
925:            const remEl = document.getElementById('remaining');
926:            remEl.className = 'stat-value ' + (remaining <= 0 ? 'danger' : remaining <= 10 ? 'warning' : 'success');
927:            
928:            // Update selected list
929:            const list = document.getElementById('selected-list');
930:            const sorted = Array.from(enabledGroups).sort();
931:            list.innerHTML = sorted.map(id => {
932:                const g = allGroups[id];
933:                return `<li class="selected-item">
934:                    <span>${g?.name || id} <small style="color: var(--text-muted);">(~${groupCounts[id] || 0})</small></span>
935:                    <span class="remove-btn" onclick="toggleGroup('${id}', false)">×</span>
936:                </li>`;
937:            }).join('');
938:        }
939:        
940:        async function loadProfile() {
941:            const name = document.getElementById('saved-profiles').value;
942:            if (!name) return;
943:            
944:            const res = await fetch(`/groups-admin/api/profiles/${name}`);
945:            const data = await res.json();
946:            
947:            if (data.error) {
948:                alert(data.error);
949:                return;
950:            }
951:            
952:            enabledGroups.clear();
953:            data.groups.forEach(g => {
954:                if (allGroups[g] && canAccessSecurity(allGroups[g].security)) {
955:                    enabledGroups.add(g);
956:                }
957:            });
958:            
959:            document.getElementById('profile-name').value = name;
960:            currentPreset = data.preset;
961:            updateUI();
962:        }
963:        
964:        async function saveProfile() {
965:            const name = document.getElementById('profile-name').value.trim() || 'default';
966:            
967:            const res = await fetch(`/groups-admin/api/profiles/${name}`, {
968:                method: 'POST',
969:                headers: { 'Content-Type': 'application/json' },
970:                body: JSON.stringify({
971:                    groups: Array.from(enabledGroups),
972:                    preset: currentPreset
973:                })
974:            });
975:            
976:            const data = await res.json();
977:            
978:            if (data.success) {
979:                const baseUrl = window.location.origin;
980:                const endpoint = baseUrl + data.mcp_endpoint;
981:                
982:                const config = {
983:                    mcpServers: {
984:                        [`op-dbus-${name}`]: {
985:                            url: endpoint
986:                        }
987:                    }
988:                };
989:                
990:                document.getElementById('endpoint-display').innerHTML = syntaxHighlight(JSON.stringify(config, null, 2));
991:                document.getElementById('config-output').classList.add('show');
992:                
993:                await loadSavedProfiles();
994:            }
995:        }
996:        
997:        function copyConfig() {
998:            const text = document.getElementById('endpoint-display').textContent;
999:            navigator.clipboard.writeText(text);
1000:            alert('Config copied!');
1001:        }
1002:        
1003:        function syntaxHighlight(json) {
1004:            return json.replace(/(".*?")(:|,)?/g, (match, key, suffix) => {
1005:                if (suffix === ':') return `<span class="json-key">${key}</span>:`;
1006:                return `<span class="json-string">${key}</span>${suffix || ''}`;
1007:            });
1008:        }
1009:        
1010:        init();
1011:    </script>
1012:</body>
1013:</html>
