238:    async fn load_next_ip(&self) -> Result<()> {
239:        let users = self.list_users().await;
240:        let mut max_octet = 2u8;
241:        for user in users {
242:            if let Some(octet) = user
243:                .assigned_ip
244:                .strip_prefix("10.100.0.")
245:                .and_then(|s| s.strip_suffix("/32"))
246:                .and_then(|s| s.parse::<u8>().ok())
247:                && octet > max_octet
248:                && octet < 255
249:            {
250:                max_octet = octet;
251:            }
252:        }
253:        let mut next_ip = self.next_ip.write().await;
254:        *next_ip = max_octet.wrapping_add(1);
255:        if *next_ip > 254 || *next_ip < 2 {
256:            *next_ip = 2;
257:        }
258:        Ok(())
259:    }
