261:    /// Get the next available IP address, ensuring no collisions
262:    pub async fn allocate_ip(&self) -> String {
263:        let mut next_ip_oct = self.next_ip.write().await;
264:        let users = self.list_users().await;
265:        let assigned_ips: std::collections::HashSet<String> =
266:            users.into_iter().map(|u| u.assigned_ip).collect();
267:
268:        for _ in 0..254 {
269:            let ip = format!("10.100.0.{}/32", *next_ip_oct);
270:            *next_ip_oct = next_ip_oct.wrapping_add(1);
271:            if *next_ip_oct > 254 || *next_ip_oct < 2 {
272:                *next_ip_oct = 2;
273:            }
274:            if !assigned_ips.contains(&ip) {
275:                return ip;
276:            }
277:        }
278:        warn!("IP address range 10.100.0.x is exhausted!");
279:        format!("10.100.0.{}/32", *next_ip_oct)
280:    }
